from django.conf import settings
from django.db import migrations, models


ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"


def forwards(apps, schema_editor):
    """silver/gold thresholds -> tier rows; member codes; open point lots; club no longer needs POS."""
    import secrets

    Settings = apps.get_model("bizsuite", "LoyaltySettings")
    Tier = apps.get_model("bizsuite", "LoyaltyTier")
    Member = apps.get_model("bizsuite", "LoyaltyMember")
    Tx = apps.get_model("bizsuite", "LoyaltyTransaction")
    Module = apps.get_model("bizsuite", "Module")

    for cfg in Settings.objects.all():
        silver = Tier.objects.create(business_id=cfg.business_id, name="نقره‌ای",
                                     min_value=cfg.silver_points, multiplier=1, color="#64748b")
        gold = Tier.objects.create(business_id=cfg.business_id, name="طلایی",
                                   min_value=max(cfg.gold_points, cfg.silver_points), multiplier=1,
                                   color="#d4a017")
        Member.objects.filter(business_id=cfg.business_id, lifetime_points__gte=gold.min_value
                              ).update(tier=gold)
        Member.objects.filter(business_id=cfg.business_id, tier__isnull=True,
                              lifetime_points__gte=silver.min_value).update(tier=silver)

    for m in Member.objects.filter(code=""):
        while True:
            code = "".join(secrets.choice(ALPHABET) for _ in range(6))
            if not Member.objects.filter(business_id=m.business_id, code=code).exists():
                break
        m.code = code
        m.save(update_fields=["code"])
        # the current balance becomes open lots (newest positive rows first)
        left = m.points_balance
        for tx in Tx.objects.filter(member=m, points__gt=0).order_by("-created_at", "-id"):
            if left <= 0:
                break
            take = min(left, tx.points)
            tx.remaining = take
            tx.save(update_fields=["remaining"])
            left -= take

    Module.objects.filter(code="club").update(requires=[], suggests=["pos"])


def backwards(apps, schema_editor):
    Module = apps.get_model("bizsuite", "Module")
    Module.objects.filter(code="club").update(requires=["pos"], suggests=[])


